#!/usr/bin/env bash
# Generates src/keyword/generated.rs from ClickHouse's parser keywords:
# the APPLY_FOR_PARSER_KEYWORDS and APPLY_FOR_PARSER_KEYWORDS_WITH_UNDERSCORES
# lists in src/Parsers/CommonParsers.h of the fetched ClickHouse checkout
# (`mise run corpus:fetch`).
#
# Usage: scripts/generate-keywords.sh [--check]
#
# With --check, nothing is written; the script fails if the checked-in file
# differs from what it would generate.
#
# The checkout's tag must match `CLICKHOUSE_VERSION` in src/lib.rs, so the
# generated file always names the release it came from.
set -euo pipefail

repo_root=$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)
corpus_dir=${CHAIRLIFT_CORPUS_DIR:-$repo_root/corpus}
clickhouse=$corpus_dir/ClickHouse
header=$clickhouse/src/Parsers/CommonParsers.h
target=$repo_root/src/keyword/generated.rs

check=false
case ${1:-} in
"") ;;
--check) check=true ;;
*)
    echo "usage: $0 [--check]" >&2
    exit 2
    ;;
esac

if [[ ! -f $header ]]; then
    echo "error: $header is missing; run scripts/fetch-corpus.sh first" >&2
    exit 1
fi

tag=$(git -C "$clickhouse" describe --tags --exact-match HEAD)
version=${tag#v}
expected=$(sed -n 's/^pub const CLICKHOUSE_VERSION: &str = "\(.*\)";$/\1/p' "$repo_root/src/lib.rs")
if [[ $version != "$expected" ]]; then
    echo "error: the ClickHouse checkout is at $version, but src/lib.rs targets $expected" >&2
    exit 1
fi

# One keyword phrase per line ("ORDER BY"), in ClickHouse's enum order.
phrases=$(awk '
    /^#define APPLY_FOR_PARSER_KEYWORDS(_WITH_UNDERSCORES)?\(/ { inside = 1; next }
    inside && /MR_MACROS\(/ {
        line = $0
        sub(/^[^"]*"/, "", line)
        sub(/".*$/, "", line)
        print line
    }
    inside && !/\\[[:space:]]*$/ { inside = 0 }
' "$header")
if [[ -z $phrases ]]; then
    echo "error: no keywords found in $header" >&2
    exit 1
fi

# Distinct upper-case words, sorted; this is the enum order.
words=$(tr ' ' '\n' <<<"$phrases" | tr '[:lower:]' '[:upper:]' | LC_ALL=C sort -u)

generate() {
    VERSION=$version WORDS=$words PHRASES=$phrases awk '
        function variant(word,    parts, n, i, name) {
            n = split(tolower(word), parts, "_")
            name = ""
            for (i = 1; i <= n; i++) {
                name = name toupper(substr(parts[i], 1, 1)) substr(parts[i], 2)
            }
            if (name !~ /^[A-Z][A-Za-z0-9]*$/) {
                print "error: cannot name a variant for " word > "/dev/stderr"
                exit 1
            }
            return name
        }
        BEGIN {
            version = ENVIRON["VERSION"]
            nwords = split(ENVIRON["WORDS"], word, "\n")
            nphrases = split(ENVIRON["PHRASES"], phrase, "\n")
            max_len = 0
            for (i = 1; i <= nwords; i++) {
                name[i] = variant(word[i])
                if (name[i] in seen) {
                    print "error: two words map to the variant " name[i] > "/dev/stderr"
                    exit 1
                }
                seen[name[i]] = 1
                by_word[word[i]] = name[i]
                if (length(word[i]) > max_len) max_len = length(word[i])
            }

            print "// @generated by scripts/generate-keywords.sh from ClickHouse " version ","
            print "// src/Parsers/CommonParsers.h. Do not edit; run the script instead."
            print ""
            print "/// The ClickHouse release the keyword list was generated from."
            print "pub(super) const SOURCE_VERSION: &str = \"" version "\";"
            print ""
            print "/// The length of the longest keyword word, in bytes."
            print "pub(super) const MAX_LEN: usize = " max_len ";"
            print ""
            print "/// A word of ClickHouse'"'"'s parser keywords, in upper case."
            print "///"
            print "/// Variants are in the byte order of their text, so `Ord` sorts keywords"
            print "/// alphabetically. Being a keyword says nothing about how the parser uses"
            print "/// a word: ClickHouse has no reserved words for identifiers."
            print "#[derive(Clone, Copy, Debug, PartialEq, Eq, PartialOrd, Ord, Hash)]"
            print "#[repr(u16)]"
            print "pub enum Keyword {"
            for (i = 1; i <= nwords; i++) {
                print "    /// `" word[i] "`"
                print "    " name[i] ","
            }
            print "}"
            print ""
            print "impl Keyword {"
            print "    /// Every keyword, in enum order."
            print "    pub const ALL: [Keyword; " nwords "] = ["
            for (i = 1; i <= nwords; i++) print "        Keyword::" name[i] ","
            print "    ];"
            print "}"
            print ""
            print "/// The text of each keyword, indexed by its discriminant."
            print "pub(super) const TEXT: [&str; " nwords "] = ["
            for (i = 1; i <= nwords; i++) print "    \"" word[i] "\","
            print "];"
            print ""
            print "/// ClickHouse'"'"'s keyword phrases (`ORDER BY`, `ADD COLUMN`, ...), in the order"
            print "/// of its `Keyword` enum."
            print "pub(super) const PHRASES: [&[Keyword]; " nphrases "] = ["
            for (i = 1; i <= nphrases; i++) {
                n = split(toupper(phrase[i]), part, " ")
                line = "    &["
                for (j = 1; j <= n; j++) {
                    line = line (j > 1 ? ", " : "") "Keyword::" by_word[part[j]]
                }
                print line "],"
            }
            print "];"
        }
    '
}

scratch=$(mktemp -d)
trap 'rm -rf "$scratch"' EXIT
generate >"$scratch/generated.rs"
rustfmt --edition 2024 --config-path "$repo_root/rustfmt.toml" "$scratch/generated.rs"

if $check; then
    if ! diff -u "$target" "$scratch/generated.rs"; then
        echo "error: $target is out of date; run scripts/generate-keywords.sh" >&2
        exit 1
    fi
    echo "$target is up to date ($version)"
else
    mkdir -p "$(dirname "$target")"
    cp "$scratch/generated.rs" "$target"
    echo "Wrote $target: $(wc -l <<<"$words") words, $(wc -l <<<"$phrases") phrases, ClickHouse $version"
fi
